BIBLIOTECA.textos({
"alphonsus-de-guimaraens-setenario-terceira-dor": {"t":["É Sião que dorme ao luar. Vozes diletas\nModulam salmos de visões contritas...\nE a sombra sacrossanta dos Profetas\nMelancoliza o canto dos levitas.\n\nAs torres brancas, terminando em setas,\nOnde velam, nas noites infinitas,\nMil guerreiros sombrios como ascetas,\nErguem ao Céu as cúpulas benditas.\n\nAs virgens de Israel as negras comas\nAromatizam com os unguentos brancos\ndos nigromantes de mortais aromas...\n\nJerusalém, em meio às Doze Portas,\nDorme: e o luar que lhe vem beijar os flancos\nEvoca ruínas de cidades mortas."],"e":{"apresentacao":"**Publicação.** Setenário das Dores de Nossa Senhora (1899), Terceira dor.\n\n**Ortografia.** Atualizada (fonte: Wikisource (pt), sem indicação de edição; texto já em ortografia atualizada, com trema)\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nNumeração na série (VI em Massaud Moisés, 1973) não confirmada; v. 11 começa em minúscula na fonte.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Terceira_dor"}]}},
"alphonsus-de-guimaraens-setenario-maos-que-os-lirios-invejam": {"t":["Mãos que os lírios invejam, mãos eleitas,\nPara aliviar de Cristo os sofrimentos,\nCujas veias azuis parecem feitas\nDa mesma essência astral dos olhos bentos:\n\nMãos de sonho e de crença, mãos afeitas\nA guiar do moribundo os passos lentos,\nE em séculos de fé, rosas desfeitas,\nEm hinos sobre as torres dos conventos:\n\nMãos a bordar o santo Escapulário,\nQue revelastes para quem padece\nO inefável consolo do Rosário:\n\nMãos ungidas no sangue da Coroa,\nDeixai tombar sobre a minha Alma em prece\nA bênção que redime e que perdoa!"],"e":{"apresentacao":"**Publicação.** Setenário das Dores de Nossa Senhora (1899)\n\n**Ortografia.** Atualizada (fonte: Wikisource (pt), sem indicação de edição; texto já em ortografia atualizada, com trema)\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nAtribuição ao livro segundo a antologia de Lauro Junkes (Roteiro da Poesia Brasileira: Simbolismo)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/M%C3%A3os_que_os_l%C3%ADrios_invejam,_m%C3%A3os_eleitas"}]}},
"alphonsus-de-guimaraens-camara-ardente-ossa-mea-i": {"t":["::epigrafe Miserere mei, Domine, quoniam infirmus sum; sana me, Domine, quoniam conturbata sunt ossa mea. (David, salmo 6, penitencial)\nDesesperanças! requiem tumultuário\nNa abandonada igreja sem Altares...\nA noite é branca, o esquife é solitário,\nE a cova, ao longe, espreita os meus pesares.\nSinos que dobram, dobras de sudário!\nNo silêncio das horas tumulares\nHá de surgir o espectro funerário,\nCujos olhos sem luz não têm olhares.\n\nSanto alívio de paz, consolo pio,\nFonte clara no meio do deserto,\nManto que cobre aqueles que têm frio!\nEis-me esperando o derradeiro trono:\nQue a Morte vem de manso, em dia incerto,\nE fecha os olhos dos que têm mais sono..."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Ossa Mea, I.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo XII, Rio de Janeiro, 1897, p. 227-231 (pré-publicação; o livro Câmara Ardente é de 1899))\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nPontuação de OCR normalizada (v. 8: ponto lido como vírgula)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazileir1218unse"}]}},
"alphonsus-de-guimaraens-camara-ardente-ossa-mea-ii": {"t":["Mãos de finada, aquelas mãos de neve,\nDe tons marfíneos, de ossatura rica,\nPairando no ar, num gesto brando e leve,\nQue parece ordenar mas que suplica...\n\nErguem-se ao longe como se as eleve\nAlguém que ante os Altares sacrifica:\nMãos que consagram, mãos que partem breve,\nMas cuja sombra nos meus olhos fica...\n\nMãos de esperança para as Almas loucas,\nBrumosas mãos que vêm brancas, distantes,\nFechar ao mesmo tempo tantas bocas...\n\nSinto-as agora, ao luar, descendo juntas,\nGrandes, magoadas, pálidas, tateantes,\nFechando os olhos das visões defuntas..."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Ossa Mea, II.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo XII, Rio de Janeiro, 1897, p. 227-231 (pré-publicação; o livro Câmara Ardente é de 1899))\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nA edição póstuma (Wikisource) traz \"Cerrando\" no último verso; aqui vale a redação da Revista Brazileira.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazileir1218unse"}]}},
"alphonsus-de-guimaraens-camara-ardente-ossa-mea-iii": {"t":["Quero crer, olhos meus em penitência,\nQue na mágoa da eterna despedida\nVos terei transformadas na áurea essência\nDe dois astros de luz amortecida...\n\nInvocareis então a alta Clemência\nDe Deus para a minha Alma dolorida,\nNo instante em que eu, sublime de inocência,\nMurmurar-vos assim, deixando a vida:\n\nOlhos de olhar o mundo contristados,\nEis-nos agora além, nesse mistério\nDe epitalâmios e de astrais noivados...\n\nVede bem que estes restos foram vossos:\nIluminai, com resplendor funéreo,\nEm noite longa, a cinza dos meus ossos..."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Ossa Mea, III.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo XII, Rio de Janeiro, 1897, p. 227-231 (pré-publicação; o livro Câmara Ardente é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazileir1218unse"}]}},
"alphonsus-de-guimaraens-camara-ardente-ossa-mea-iv": {"t":["Oh lábios que sereis de lodo e poeira,\nQue intangível desejo vos abate?\nQue ânsia suprema, na hora derradeira,\nEm silêncio vos livra esse combate?\n\nQuereis falar, e quietos sois: na inteira\nMudez do coração que já não bate,\nPor debaixo de vós ri-se a caveira,\nLábios que fostes chamas de escarlate.\n\nSe frios como neve estais agora,\nCom saudades dos beijos que não destes,\nAlegrai-vos na dor que vos descora,\nCerrai-vos para sempre em doce calma:\nQue os beijos dados, e ainda os mais celestes,\nNunca deixam vestígios na nossa Alma..."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Ossa Mea, IV.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo XII, Rio de Janeiro, 1897, p. 227-231 (pré-publicação; o livro Câmara Ardente é de 1899))\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\n\"ancia\" (v. 3): OCR \"anciã\", corrigido (ânsia)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazileir1218unse"}]}},
"alphonsus-de-guimaraens-camara-ardente-ossa-mea-v": {"t":["Braços abertos, uma Cruz... Basta isto,\nMeu Deus, na cova abandonada e estreita\nOnde repouse quem te for benquisto,\nCorpo de uma Alma que te seja afeita.\n\nÉ o Justo. As chagas celestiais de Cristo\nBeijam-lhe mãos e pés: purpúreo deita\nO pobre lado traspassado o misto\nDe água e de sangue. É o Justo. Eis a Alma Eleita.\n\nA coroa de espinhos irrisória\nMagoa-lhe a cabeça, e pelas costas\nCai-lhe o manto dos reis em plena glória...\n\nGlória de escárnio o manto extraordinário:\nMas quem me dera um dia, de mãos postas,\nNele envolver-me como num sudário!"],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Ossa Mea, V.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo XII, Rio de Janeiro, 1897, p. 227-231 (pré-publicação; o livro Câmara Ardente é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazileir1218unse"}]}},
"alphonsus-de-guimaraens-camara-ardente-ossa-mea-vi": {"t":["Ah! tantas ilusões, para as perdermos,\nE os sonhos onde iremos enterrá-los!\nE sempre o luar na solidão sem termos,\nE estes corpos a encher covas e valos...\n\nVamos rezar além, naqueles ermos.\nQuem poderá sofrer tantos abalos!\nOs pobres corações estão enfermos,\nE o consolo de Deus deve salvá-los.\n\nTomba de joelhos, tu que não soubeste\nGozar a paz que veio sobre as ondas\nDa tua Alma ao clarão da noite agreste...\n\nNoivo da Morte em branca primavera,\nSe acaso tens um leito onde te escondas,\nAperta a mão piedosa que te espera..."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Ossa Mea, VI.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo XII, Rio de Janeiro, 1897, p. 227-231 (pré-publicação; o livro Câmara Ardente é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazileir1218unse"}]}},
"alphonsus-de-guimaraens-camara-ardente-ossa-mea-vii": {"t":["Se eu procurasse a minha cova ausente,\nBem pode ser à beira desta estrada\nAnte a minha Alma a visse de repente,\nBoca vazia ao luar escancarada...\n\nMas nessa hora de horrores que pungente\nEspanto! Alma no amor crucificada,\nBranca, fugindo silenciosamente,\nTalvez que o teu olhar não visse nada.\n\nTanto é certo, meu Deus, na vida impura\nNão podermos saber onde marcados\nEstão os palmos de cada sepultura...\n\nPois, talvez, ao crepúsculo indeciso\nQue me encaminha os passos fatigados,\nSeja-me a cova o chão que agora piso..."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Ossa Mea, VII.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo XII, Rio de Janeiro, 1897, p. 227-231 (pré-publicação; o livro Câmara Ardente é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazileir1218unse"}]}},
"alphonsus-de-guimaraens-camara-ardente-pulchra-ut-luna": {"t":["Celeste... É assim, divina, que te chamas.\nBelo nome tu tens, Dona Celeste...\nQue outro terias entre humanas damas,\nTu que embora na terra do céu vieste?\n\nCeleste... E como tu és do céu não amas:\nForma imortal que o espírito reveste\nDe luz, não temes sol, não temes chamas,\nPorque és sol, porque és luar, sendo celeste.\n\nIncoercível como a melancolia,\nAndas em tudo: o sol no poente vasto\nPede-te a mágoa do findar do dia.\n\nE a lua, em meio à noite constelada,\nPede-te o luar indefinido e casto\nDa tua palidez de hóstia sagrada."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Pulchra ut Luna, II.\n\n**Ortografia.** Atualizada (fonte: Wikisource (pt), sem indicação de edição; texto já em ortografia atualizada, com trema)\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nAtribuição ao livro e numeração \"II\" segundo a antologia de Massaud Moisés (1973); conferir na edição de 1899.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pulchra_ut_Luna"}]}},
"alphonsus-de-guimaraens-camara-ardente-arias-e-cancoes-ii": {"t":["A suave castelã das horas mortas\nAssoma à torre do castelo. As portas,\nQue o rubro ocaso em onda ensanguentara,\nBrilham do luar à Luz celeste e clara.\nComo em órbitas de fatais caveiras\nOlhos que fossem de defuntas freiras,\nOs astros morrem pelo céu pressago...\nSão como círios a tombar num lago.\nE o céu, diante de mim, todo escurece...\nE eu nem sei de cor uma só prece!\nPobre Alma, que me queres, que me queres?\nSão assim todas, todas as mulheres."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Árias e Canções, II.\n\n**Ortografia.** Atualizada (fonte: Wikisource (pt), sem indicação de edição; texto já em ortografia atualizada, com trema)\n\n**Forma.** Dísticos decassílabos.\n\n**Notas sobre o texto.**\n\nA página do Wikisource junta os poemas II e X sem separação; atribuição ao livro e numeração segundo Massaud Moisés (1973)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/%C3%81rias_e_can%C3%A7%C3%B5es"}]}},
"alphonsus-de-guimaraens-camara-ardente-arias-e-cancoes-x": {"t":["Hirta e branca... Repousa a sua áurea cabeça\nNuma almofada de cetim bordada em lírios.\nEi-la morta afinal como quem adormeça\nAqui para sofrer Além novos martírios.\n\nDe mãos postas, num sonho ausente, a sombra espessa\nDo seu corpo escurece a luz dos quatro círios:\nEla faz-me pensar numa ancestral Condessa\nDa Idade Média, morta em sagrados delírios.\n\nOs poentes sepulcrais do extremo desengano\nVão enchendo de luto as paredes vazias,\nE velam para sempre o seu olhar humano.\n\nExpira, ao longe, o vento, e o luar, longinquamente,\nAlveja, embalsamando as brancas agonias\nNa sonolenta paz desta Câmara-ardente..."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899), Árias e Canções, X.\n\n**Ortografia.** Atualizada (fonte: Wikisource (pt), sem indicação de edição; texto já em ortografia atualizada, com trema)\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nA página do Wikisource junta os poemas II e X sem separação; estrofação 4-4-3-3 segundo Massaud Moisés (1973)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/%C3%81rias_e_can%C3%A7%C3%B5es"}]}},
"alphonsus-de-guimaraens-camara-ardente-olhos-sublimes": {"t":["::epigrafe Per istam Sanctam Unctionem, et suam piissimam misericordiam, indulgeat tibi Dominus quidquid peccasti per visum, per auditum, per odoratum, per gustum, per tactum, per incessum...\nOlhos sublimes, onde os Anjos cantam salmos\nLonge do resplendor das paixões transitórias:\nE vós, conchas do Amor de Deus, ouvidos almos,\nQue nada ouvistes a não ser hinos e glórias:\n\nLábios em oração, dolentemente calmos,\nQue repetistes sempre as Sagradas Memórias:\nVós, brancas mãos, que já tínheis medido os palmos\nDa cova incerta, vós, brancas mãos incorpóreas:\n\nPés doloridos, pés de arminho, acostumados\nA caminhar por sobre o chão dos cemitérios\nE de pisar no mundo impuro fatigados:\n\nLábios pungentes, mãos e pés, olhos e ouvidos,\nQuietos e frios para sempre entre mistérios,\nPor toda a eternidade eternamente ungidos!"],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899)\n\n**Ortografia.** Atualizada (fonte: Wikisource (pt), sem indicação de edição; texto já em ortografia atualizada, com trema)\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nEstrofação 4-4-3-3 (a do Wikisource está deslocada); atribuição ao livro segundo a antologia de Lauro Junkes (Roteiro da Poesia Brasileira: Simbolismo)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Olhos_sublimes,_onde_os_Anjos_cantam_salmos"}]}},
"alphonsus-de-guimaraens-camara-ardente-responsorium": {"t":["Alma que teve quem dela se recordasse\nNa ignóbil terra infiel onde tudo se esquece:\nRequiescat in pace.\n\nCorpo a esperar que o Noivo-Esperado chegasse,\nRosa autunal que o sol do Amor não mais aquece:\nRequiescat in pace.\n\nOlhar que se apagou sem que nunca pecasse,\nCiliciado altair que entre luares floresce:\nRequiescat in pace.\n\nLábio que dera a quem neste mundo a beijasse\nA luz espiritual de uma longínqua prece:\nRequiescat in pace.\n\nBeijo, fruto estival que lhe floriu na face,\nEvocador de tão prometedora messe:\nRequiescat in pace.\n\nCabelo, pôr-do-sol que entre neves brilhasse,\nNuvem dispersa além quando a tarde anoitece:\nRequiescat in pace.\n\nAlma que teve quem dela se recordasse\nNa ignóbil terra infiel onde tudo se esquece:\nRequiescat in pace."],"e":{"apresentacao":"**Publicação.** Câmara Ardente (1899)\n\n**Ortografia.** Atualizada (fonte: Wikisource (pt), sem indicação de edição; texto já em ortografia atualizada, com trema)\n\n**Forma.** Tercetos com refrão.\n\n**Notas sobre o texto.**\n\nAtribuição ao livro (Câmara Ardente) provável, não confirmada em edição de 1899; conferir.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Responsorium"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-i": {"t":["::epigrafe Et ascendit super cherubim, et volavit: volavit super pennas ventorum.\nNa solidão suprema dos conventos,\nEm hora de pavor tão sossegadas,\nVêm-se passar fantasmas sonolentos,\nVultos de Freiras mortas que são Fadas.\n\nSoluça a paz dos grandes monumentos,\nDebruçados à beira das estradas;\nSombras de luto, pelos lutulentos\nCaminhos, choram mágoas já choradas.\n\nVozes de além, pungentes de mistério,\nCantam: e os sinos dobram nas ermidas,\nAcompanhando o canto-chão funéreo...\n\n(Brancas visões remotas, enfadonho\nEnterro infindo de ilusões queridas,\nNa solidão suprema do meu Sonho!)"],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", I.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\n\"sossegadas\" (v. 2): OCR \"so cegadas\"; leitura conjectural pela rima e pelo sentido.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-ii": {"t":["Envolvesse-me a santa beatitude\nDos olhos que chorei por não mais vê-los,\nE os remorsos que adivinhar não pude\nTalvez surgissem de eriçados pelos.\n\nBem pode ser que a Virgem da virtude,\nNeve na face, ocaso nos cabelos,\nViesse mostrar-me a sombra que me ilude,\nCortejada por tantos pesadelos.\n\nE a beatitude desses olhos, casta,\nPurificando a culpa que me exila,\nDar-me-ia o Reino que de mim se afasta.\n\nE sem mancha, a minha Alma, que o Céu guarde,\nBem pode ser que voasse na tranquila\nDolência conventual do fim da tarde..."],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", II.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-iii": {"t":["Lábios formados para a prece, face\nAfeita à luz dos círios, e tão brando\nOlhar, às vezes quem a contemplasse,\nSe não chorasse, ficaria orando...\n\nE sempre, triste como o luar que nasce,\nA erma expressão do rosto miserando\nContemplava-se: e então, como eu a amasse,\n(Celestial...) surpreendia-me chorando.\n\nOh! Senhora das Dores, que saudade\nNão tenho dela ao ver a vossa glória,\nCheia de bênçãos e de claridade!\n\nLonge do Céu, foi rápida e sombria,\nComo sucede aqui, a sua história:\nMorreu, e bem sabeis porque morria..."],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", III.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-iv": {"t":["A palidez de algumas Virgens clama\nPor uma vida que será tranquila.\n(Se a voz, que por aqui passou, vos chama,\nÉ bom que vades para bem ouvi-la...\n\nA perfeição, que de astros se recama,\nDentro de nós por tal Amor cintila:\nNada melhor que o Céu para quem ama...\nÉ a voz de Deus, e bem podeis segui-la.)\n\nDessas Virgens tu és quem mais espera...\nNenhuma tem a cor do teu semblante,\nNem o pesar de amor que te macera.\n\nO teu olhar é de quem tem saudades:\nRecordas-te talvez da vida errante\nQue viveste no caos de outras idades..."],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", IV.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\n\"côr\" (v. 10): OCR \"cto\", corrigido.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-v": {"t":["Que olhar de Monja em longa penitência\nO olhar daqueles olhos macerados!\nPairava-lhe talvez na morna essência\nUma Alma carregada de pecados.\n\nPara que mundos, para que existência,\nTão além desta vida, ei-los voltados!\nOh inacessível, mística dolência\nDe uns olhos a sonhar outros noivados...\n\nVoz do passado, som que ressuscita!\nOlhar tão cheio de palavras mortas\nD'aqui por certo que não pode ser...\n\nAlma, para me ver, Alma bendita,\nPõe-te de luto nessas duas portas\nCom uma tristeza de quem vai morrer."],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", V.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-vi": {"t":["Outro, não eu, estranhará que admires\nA grande luz daquele olhar pungente\nQue tem todas as cores de um arco-íris:\nQue estranhe quem não ama e quem não sente.\n\nNem tu rirás, por certo, se me ouvires\nFalar de uns olhos religiosamente:\nÍsis, a deusa casta, e o fulvo Osíris\nDeram-lhes toda a profundez clemente.\n\nOlhar de amor, luares de lua... Vivo\nA vida excelsa de um contemplativo\nOs pés na terra, a Alma pairando no ar...\n\nHá mulheres que a gente diz ao vê-las:\nOlhos cheios de nuvens e de estrelas...\nVive com Deus quem tem o Céu no olhar."],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", VI.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-vii": {"t":["Piedosa: o olhar nunca baixou à terra.\nFitava o Céu porque era pura e santa...\nTinha o orgulho fidalgo de uma Infanta\nQue entre escudeiros e lacaios erra.\n\nDeusa nenhuma, por mais alta, encerra\nEm se, talvez, misericórdia tanta:\nAinda hoje na minha Alma se alevanta\nComo uma cruz no cimo de uma serra.\n\nFoi-lhe a vida um eterno mês de maio,\nCheio de rezas brancas a Maria,\nQue ela vivera como num desmaio.\n\nTão branca assim! Fizera-se de cera...\nSorriu-lhe Deus, e ela que lhe sorria,\nVirgem voltou como do Céu descera."],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", VII.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-dona-mistica-alma-viii": {"t":["Olhos sacramentais, olhos contritos,\nOnde soluçam mágoas e pesares,\nSonhando o Céu miseramente fitos\nNo oculto resplendor de outros Altares:\n\nOlhos sacramentais, olhos benditos,\nTão alheios à dor dos meus olhares,\nTão cheios dos mistérios infinitos\nDas horas de paixão crepusculares:\n\nOlhos que refletis velhas memórias\nDos séculos da Crença e dos Martírios,\nInsensíveis às coisas transitórias:\n\nOlhos sacramentais, eterizados,\nE que esperais por mim como dois círios,\nQuando ouvirei os dobres dos finados?"],"e":{"apresentacao":"**Publicação.** Dona Mística (1899), \"Alma\", VIII.\n\n**Ortografia.** Atualizada (fonte: Revista Brazileira, tomo VIII, Rio de Janeiro, 1896, p. 356-360 (pré-publicação; o livro Dona Mística é de 1899))\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/revistabrazilei08unkngoog"}]}},
"alphonsus-de-guimaraens-kiriale-initium": {"t":["::dedicatoria Ao meu primo Horácio Bernardo Guimarães\n\nTanta agonia, dores sem causa,\nE o olhar num céu invisível posto...\nPrantos que tombam sem uma pausa,\nRisos que não chegam mais ao rosto...\n\nNoites passadas de olhos abertos,\nSem nada ver, sem falar, tão mudo...\nAlguém que chega, passos incertos,\nAlguém que foge, e silêncio em tudo...\n\nSó, perseguido de sombras mortas,\nDe espectros negros que são tão altos...\nOuvindo múmias forçar as portas,\nE esqueletos que me dão assaltos...\n\nSó, na geena deste meu quarto\nCheio de rezas e de luxúria...\nAlguém que geme, dores de parto,\n—Satan que faz nascer uma fúria...\n\nE ela que vem sobre mim, de braços\nEscancarados, a agitar as tetas...\nE nuvens de anjos pelos espaços,\nAnjos estranhos com as asas pretas...\n\nE o inferno em tudo, por tudo o abismo\nEm que se me vai toda a coragem...\n«Santa Maria, dá-me o exorcismo\nDo teu sorriso, da tua imagem!»\n\nE os pesadelos fogem agora...\nTalvez me escute quem se levanta:\nE' a lua... e a lua é Nossa-Senhora,\nSão dela aquelas cores de Santa!"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, I.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (7 estrofes, 28 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-a-cabeca-de-corvo": {"t":["::dedicatoria Ao Dr. Edmundo Lins\n\nNa mesa, quando em meio à noite lenta\nEscrevo antes que o sono me adormeça,\nTenho o negro tinteiro que a cabeça\nDe um corvo representa.\n\nA contemplá-lo mudamente fico\nE n'uma dor atroz mais me concentro:\nE entreabrindo-lhe o grande e fino bico,\nMeto-lhe a pena pela guela a dentro.\n\nE solitariamente, pouco a pouco,\nDo bojo tiro a pena, rasa em tinta...\nE a minha mão, que treme toda, pinta\nVersos próprios de um louco.\n\nE o aberto olhar vidrado da funesta\nAve que representa o meu tinteiro,\nVai-me seguindo a mão, que corre lesta,\nToda a tremer pelo papel inteiro.\n\nDizem-me todos que atirar eu devo\nTrevas em fora este agoirento corvo,\nPois dele sangra o desespero torvo\nDestes versos que escrevo."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, II.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (5 estrofes, 20 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-o-cachimbo": {"t":["::dedicatoria A Joaquim Soares Maciel Junior\n\nUma visão do tenebroso Limbo,\nSoturna e sepulcral, tens a teu lado:\nPor um artista foi este cachimbo\nA' feição de caveira burilado.\n\nVê tu, formosa, é um crânio em miniatura\nOnde a tua caveira vou revendo:\nO vazio das órbitas fulgura,\nSinistramente, quando à noite o acendo.\n\nE às vezes, quando o eterno ideal me abrasa\nO crânio, no cachimbo os olhos ponho:\nHá também dentro dele fogo em brasa,\nSobe o fumo e desfaz-se como um sonho.\n\nE quando à noite o acendo, a sua boca\nTransparente e maguada se clareia:\nE ri-se, e eu rio ao vê-la, aberta e louca,\nToda de beijos e de afagos cheia."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, III.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (4 estrofes, 16 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-o-leito": {"t":["Ontem, à meia noite, estando junto\nA uma igreja, lembrei-me de ter visto\nUm velho que levava às costas isto:\nUm caixão de defunto.\n\nO caso nada tem de extraordinário.\nQuem um velho a levar um caixão tal\nInda não viu? É um fato quase diário\nEm qualquer bairro de uma capital.\n\nMas é que ia de modo tal curvado\nPara o chão, e a falar tão baixo e tanto,\nQue, manso e manso, e trêmulo de espanto,\nFui seguindo a seu lado.\n\nDisse-lhe assim: «Talvez seja a demência\nQuem guie os passos todos que tu dês;\nOu és então, na mísera existência,\nUm miserável bêbedo, talvez.»\n\nO olhar fito no chão, como desfeito\nEm sangue, o velho, sem me olhar, seguia.\nE ouvi-lhe a unica frase que dizia:\n—«Vou levando o meu leito.»"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, IV.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (5 estrofes, 20 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-luar-sobre-a-cruz-da-tua-cova": {"t":["Sonhei que estava no cemitério,\nRezando sempre rezas de cor.\nE como o luar clareasse o chão do cemitério,\nPensei num mundo que é talvez melhor.\n\nBranca de linho como um fantasma,\nA torre grande era só tristeza.\nE como envolta em luar, muito maguada e pasma,\nEstava ao longe não sei que Princesa.\n\nEra talvez a Desesperança,\nCom o seu cortejo de sonhos maus.\n(Demônios, dai começo à vossa contradança,\nVinde cantar os lânguidos solaus!)\n\n«Certo o coração de tudo esquece,\nQuando muitos anos são passados...»\nE eu não te esqueço mais, alma da minha prece,\nQue voaste para os mundos encantados!\n\n«Eu sei que o amor sempre se renova,\nE que ninguém pode viver só...»\nE como o luar clareasse a cruz da tua cova,\nVi o meu sonho transformado em pó."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, V.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (5 estrofes, 20 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-presagios": {"t":["«Um esqueleto de mantilha\nQue passa pela minha porta...\n(Um velho diz) é minha filha\nQue vai morrer ou que está morta!»\n\n«Um esqueleto agonisante\nQue passa pela minha porta...\n(Um moço diz) é minha amante\nQue vai morrer ou que está morta!»\n\nOutro dirá: «É meu presságio,\nVendo-o que passa pela porta,\nO irmão que morre num naufrágio,\nOu a irmã querida que está morta!»\n\nOutro: «Se és tu, meu pobre amigo,\nQue passas pela minha porta!»\n«Se és tu, meu pai, eu vou comtigo...\nSe é minha mãe, oh Deus, que é morta!»\n\nNenhum de nós, porém, ao vê-lo\n(Quem se não julga rijo e forte?)\nDirá que o horrendo pesadelo\nNos anuncia a própria morte..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, VIII.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (5 estrofes, 20 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-a-meia-noite": {"t":["::dedicatoria A Aug. de Viana do Castelo\n\nCheguei à meia-noite em ponto.\nO caso deu-se como eu conto,\nCheio de lúgubre mistério...\nPois ela disse: «Ao cemitério\nVamos à meia-noite em ponto.»\n\nE eu respondi-lhe: «Conto, conto\nComtigo à meia-noite em ponto.»\n\nComo eu sabia, ela outro amante\nTivera em tempo não distante.\nEra já morto: eu uma esposa\nTinha também sob uma lousa.\nE ela sabia dessa amante.\n\nJaziam, um do outro distante,\nO amante dela e a minha amante.\n\nBem não chegamos, os ciprestes\nAgitaram as verdes vestes\nComo arrojando-se debruços...\nQue ais de tristeza e que soluços\nGemeram tão verdes ciprestes.\n\nGemia o vento pelas vestes\nVerdes dos virides ciprestes.\n\nParamos de repente à porta:\nEu era um morto, ela uma morta.\nTal foi a cena branca e nua\nQue nós, clareados pela lua,\nOlhamos bem ao pé da porta.\n\nEu era um morto, ela uma morta,\nSem movimento junto à porta.\n\nDiante de nós, em frente, diante,\nO amante dela e a minha amante,\nEspectros vis num mesmo quadro,\nVinham vagar, hirtos, pelo adro,\nDiante de nós, em frente, diante...\n\nO amante dela e a minha amante\nRiram, passando para diante."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, IX.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quintilhas alternadas com dísticos (35 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-cancao": {"t":["::dedicatoria Ao meu irmão Arch'Angelus\n\nEu cantei, como vós, oh trovadores,\nE ninguém quiz ouvir os meus amores.\n\nCantei meus versos junto às morenas,\nRiram-se todas das minhas penas.\n\nE junto às loiras, dias inteiros,\nCantei meus sonhos aventureiros.\n\n(Riram-se todas, dias inteiros,\nDesses meus sonhos aventureiros.)\n\nSabia trovas de montanheses,\nCanções longínquas dos Portugueses.\n\nPerdi-me em sonhos por sobre os mares...\nNinguém quiz ouvir os meus cantares.\n\n(Riram-se todas, dias inteiros,\nDesses meus sonhos aventureiros).\n\nNa tua cova só tu me ouviste...\nQuem sabe lá se também te riste!"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, X.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Dísticos (8 estrofes, 16 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-o-campanario": {"t":["::dedicatoria A José Inácio de Araújo Lima\n\nNo campanário, ao sol incerto,\nNão há sineiros nem há sinos...\nSe alguém morrer aqui por perto,\nNão terá dobres vespertinos,\nLamento de almas no deserto.\n\nJá não há sinos nem sineiros\nNo campanário em abandono...\nBastam, talvez, os carpinteiros\nA trabalhar dias inteiros,\nDando leitos a quem tem sono.\n\nNenhuma cruz, abrindo os braços,\nVela por quem já não existe...\nNo chão pisado não há traços\nDe joelhos, mas somente passos\nIndiferentes de algum triste.\n\nJunto deste caixão informe\nNinguém reza de joelhos juntos...\nBasta, talvez, a cova enorme\nPara abrigar o homem que dorme\nNo campo-santo dos defuntos.\n\nSó, na Capela entristecida,\nQue dorme sobre a encosta agreste,\nNossa-Senhora, a Dolorida,\nVem apontar-nos a outra vida,\nOlhando o Céu com o olhar celeste.\n\nE no Altar-Mor, cheio de palmas,\nNo claro-escuro de um sol-posto,\nNosso-Senhor recebe as almas,\nAbrindo as pálpebras tão calmas\nPor entre as chagas do seu rosto.\n\nNo seu olhar de Abandonado,\nPois a Capela está vazia,\nFulgura o humano luar sagrado\nQue arranca os homens do pecado\nE de Jesus nos faz um dia.\n\nJá não há sinos nem sineiros\nNo campanário em abandono...\nSob a sombra dos salgueiros\nEle aparece nos outeiros\nComo um solar que não tem dono.\n\nAh! como é triste, ao sol incerto,\nLonge da voz santa dos sinos...\nPara guiar-nos ao céu aberto\nJá não tem dobres vespertinos\nO campanário do deserto."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, XIII.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quintilhas (9 estrofes, 45 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ladainha-dos-quatro-santos": {"t":["Santa Maria, Mãe de Jesus,\nQue com as asas protetoras cobres\nOs que têm frio, rotos e nus,\nOra pro nobis.\n\nSanto José, pobre carpinteiro,\nQue eras tão pobre entre os que eram pobres,\nDe enxó na mão. Santo verdadeiro,\nOra pro nobis.\n\nSanto Jesus, meu bom Protetor,\nQue nos teus grandes olhos encobres\nO céu. Cordeiro e também Pastor,\nOra pro nobis.\n\nSanta Morte, afinal, cujo nome,\nOuvido aos sons dos últimos dobres,\nSerá o consolo dos que têm fome.\nOra pro nobis."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput I, Pulvis, XIV.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (4 estrofes, 16 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-naufrago": {"t":["::epigrafe J'étais mort sans surprise, et la terrible aurore / M'enveloppait. — Eh quoi! n'est-ce donc que cela? (C. Baudelaire)\n\nE temo, e temo tudo, e nem sei o que temo.\nPerde-se o meu olhar pelas trevas sem fim.\nMedonha é a escuridão do céu, de extremo a extremo...\nDe que noite sem luar, mísero e triste, vim?\n\nAmedronta-me a terra, e se a contemplo, tremo.\nQue mistério fatal corveja sobre mim?\nE ao sentir-me no horror do caos, como um blasfemo,\nNão sei porque padeço, e choro, e anceio assim.\n\nA saudade tirita aos meus pés: vai deixando\nAtraz de si a magua e o sonho... E eu, miserando,\nCaminho para a morte alucinado e só.\n\nO naufrágio, meu Deus! Sou um navio sem mastros.\nComo custa a minha alma a transformar-se em astros,\nComo este corpo custa a desfazer-se em pó!"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, I.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-poeiras-medievaes": {"t":["É a furna absconsa ao pé de um tremedal tremendo.\nSoluçam gênios maus numa região de peste.\nSem ar, sujeito ao sono insólito, distendo\nOs nervos doentes. Passa arfante o vento leste.\n\nAh! se eu fosse contar as Mortas que estou vendo...\nUm demônio latino anda em roda. Celeste\nÉ a cor do manto azul de um feiticeiro horrendo.\nOutro de cornos há que de rubro se veste.\n\nFidalgos tristes vêm afrontando perigos,\nAlma que em frente ao céu desolado se ajoelha.\nGrande olhar velador dos Cruzados antigos...\n\nNinguém verá jamais o caos de sangue e trevas\nOnde estou, envolvido em mortalha vermelha,\nNas ruinas augurais destas poeiras medievas."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, II.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-visao-dos-solitarios": {"t":["Com a vasta escuridão do teu cabelo ensombras,\nSe o destranças pelo ar, o próprio sol que bate\nNessa carne que tem a maciez das alfombras\nFeitas de seda branca e veludo escarlate.\n\nNão sei quem és; atrais e ao mesmo tempo assombras,\nAlguma coisa de astro o teu sorriso dá-te...\nErrante multidão de espectros e de sombras\nAnda em redor de ti como para um combate.\n\nPara que, para que tanta magua me deste?\nPorque surgiste aqui, na minha noite espessa,\nTu, Rainha imortal de algum Sabá celeste?\n\nFantasma, és a Mulher! Levanta-te, Anjo eterno!\nErgue-te mais, e mais! Como a tua cabeça\nPode tocar o Céu, se tens os pés no Inferno?"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, III.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-vedeta": {"t":["Certo, eu vivo num mundo espiritual, postado\nÀ beira de uma vil sepultura de gesso.\nSem que possa fugir, vejo a Morte ao meu lado...\nQue vale o pó (... foste mulher!) porque padeço?\n\nPobres restos mortais! (O lábio do pecado\nNunca beijou de leve o teu cabelo espesso...\nO teu remoto olhar de Anjo Crucificado\nVem-me de longe despertar quando adormeço.)\n\nParce sepultis, Deus dos eternos martírios!\nUm coveiro, talvez, vendo a cova tão alta,\nFez o canteiro onde nós dois colhemos lírios.\n\nSei de um espectro que me diz quando se some:\n— A quem guardas aí, Cavaleiro de Malta,\nÀ beira deste Santo-Sepulcro sem nome?"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, IV.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-espirito-mau": {"t":["::dedicatoria A Coelho Neto\n\nUm espírito mau passa rezando ofícios\nNa minha alma que está toda cercada de eças.\nE patriarcas senis vêm mostrar-me cilícios,\nFalam no Purgatório, e vão fugindo às pressas.\n\nFeiticeiras que vendem virtudes e vícios,\nFadas que leem nas mãos as ignotas promessas,\nDizem que hei de sofrer sobre-humanos suplícios...\nSatanases também dizem coisas como essas.\n\nEspectros que têm voz, sombras que têm tristeza,\nPerseguem-me; e acompanho os apagados traços\nDe semblantes que amei fora da natureza.\n\nVós haveis de fugir ao som de padre-nossos,\nFrutos da carne infiel, seios, pernas e braços,\nE vós, múmias de cal, dansa macabra de ossos!"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, V.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-succubus": {"t":["Às vezes, alta noite, ergo em meio da cama\nO meu vulto de espectro, a alma em sangue, os cabelos\nHirtos, o torvo olhar como raso de lama,\nSob o tropel de um batalhão de pesadelos.\n\nPelo meu corpo todo uma Fúria de chama\nEnrosca-se, prendendo-o em satânicos elos:\n— Vai-te, Demônio encantador, Demônio ou Dama,\nLoira Fidalga infiel dos infernais Castelos!\n\nComo um danado em raiva horrenda, clamo e rujo:\nHausto por hausto aspiro um ar de enxofre: tento\nErguer a voz, e como um réptil escabujo.\n\n— Quem quer que sejas, vai-te, oh tu que assim me assombras!\nAcordo: o céu, lá fora, abre o olhar sonolento,\nCheio de compuncção dos luares e das sombras."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, VI.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-serpes": {"t":["Tantas serpentes vi pelos meus calcanhares\nEm rolos, e tal era a fúria dos seus botes,\nE tantas rans coaxando, e as vozes familiares\nDe outros muitos répteis a pular aos pinotes:\n\nTantos monstros, que emfim os meus rudes olhares\n(Dizem que os Anjos têm os mais excelsos dotes.)\nTiveram de rezar à sombra dos altares,\nSuplicando a verdade à voz dos sacerdotes.\n\nEis-me esperando aqui os meus votos supremos:\nTerão a treva ou a luz, o Inferno ou o Paraíso,\nOs pobres olhos que não mais serão blasfemos?\n\nComo é bom esperar a longínqua promessa\nQue no dia final do tremendo Juizo\nHá de ser tão maior por maior que se peça!"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, VII.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-spectrum": {"t":["::parte VIII\n::parte I\n\nVestido de ouro o Sol, bom padre, canta a missa\nDa luz no altar do céu. Véus de celestes damas,\nAs nuvens voam: cantam pássaros: e viça\nMais do que nunca o olhar de Flora pelas ramas.\n\nEntra o Espectro. Com voz soluçante e submissa\nMurmuro-lhe: — «Porque, se és luz, se já não amas,\nAtormentar-me assim? Não haverá justiça\nFinal no inferno, fogo eterno, eternas chamas?\n\nPara que perseguir-me, Anjo tristonho? Espera.\nOu antes de noite vem, quando o remorso chora,\nE o luto os olhos fecha à alma da primavera.»\n\n— «Bem te deves lembrar: quando tu me esqueceste,\nBrilhava o mesmo sol no mesmo céu de agora...\nBem te deves lembrar: foi um dia como este.»\n\n::parte II\n\nE o Espectro, que era um Anjo espiritual, esvoaça\nPelo ar tranquilo, e sobe ao céu. Noite silente.\nToda de branco, a lua, ancila triste, passa\nPelo mosteiro celestial, celestialmente.\n\nEstrelas de um fulgor de diamantes sem jaça\nBrilham na concha azul do céu de outubro quente.\nHoras passam. De novo o Espectro vem. — «Por graça\nDeixa-me em paz, deixa-me em paz eternamente.\n\nOu antes mais tarde vem, quando a treva de rastros\nEnvolve a terra, quando o céu negro recua\nPara mais alto, e chora os semi-mortos astros.»\n\n— «Quando eu morri, hora fatal, hora funesta,\nEra uma noite assim, toda branca de lua...\nBem te deves lembrar: a noite era como esta.»"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, VIII.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** 2 sonetos.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-sam-graal": {"t":["Se a tentação chegar há de achar-me rezando\nNa erma Tebaida do meu sonho solitário.\n(Miséria humana, humano vício miserando,\nNão haveis de poluir as hóstias no Sacrário...)\n\nSe a tempestade vier há de achar-me chorando,\nE como dobrareis, sinos do Campanário!\nSubirei à montanha eleita orando, orando...\n(Não és tão longa assim, ladeira do Calvário!)\n\nSe a tentação chegar há de achar-me de joelhos,\n(Miséria humana, humanidade miseranda...)\nMaldizendo a traição dos seus lábios vermelhos.\n\nSe a tempestade vier, e eu cair, nesse dia\nPiedosamente irei pela terra em demanda\nDe ti, oh Santo Craal, Vaso da Eucaristia!"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, IX.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-recordando-se": {"t":["Aberta a pobre mão como a pedir a morte,\nOlhos que vinham de mais longe que os poentes,\nEla surgiu-me branca e pura de tal sorte\nQue vi passar por mim sombras inexistentes.\n\nGemei, gemei ao luar, vento sul, vento norte!\nE com toda a fluidez dos seus olhos doentes,\nOlhou-me calma e triste... (Oh pálida consorte,\nQuem pudera chorar as saudades que sentes!)\n\nOlhos não vistos, céu de nimbos, mar de escolhos,\nEla abaixou-vos para o chão com gesto brando,\nPorque o céu ninguém pode abrangê-lo com os olhos.\n\nComo quem se recorda olhou para os caminhos.\n(Há tantos anos já que te vi soluçando\nAos pés do Senhor Bom Jesus de Matosinhos!)"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, X.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-pobres-sonhos": {"t":["Meus pobres sonhos que sonhei, já tão sonhados,\nQue vento de desdita e de luto vos leva?\nQue fúria sem pavor, sedenta de pecados,\nVos guia em turbilhões de poeira e de treva?\n\nE quem vos faz errar sem crença, aniquilados\nPor tal desesperança amargurada e seva,\nQue vos vejo adejar, tantos anos passados,\nNo mesmo céu de sangue onde a morte se eleva?\n\nSonhos, nuvens do amor, espectros da saudade,\nSe o desespero há de chegar um dia destes,\nOh dai-me fé, dai-me esperança e caridade.\n\nE hei de ver-vos voltar, como as visões primeiras,\nMeus pobres sonhos que no inferno vos perdestes,\nSob o clarão das tres virtudes verdadeiras..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, XI.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-in-hoc-signo": {"t":["Bem me valeu rezar e ser humilde e justo,\nErguer ao céu piedoso os olhos compassivos:\nO dragão que eu temia apareceu-me, o busto,\nFulvo, no resplendor dos clarões redivivos...\n\nTombei de joelhos, sem poder lutar, a custo,\nDiante da luz de sete olhos contemplativos.\nBrilhava um sol qualquer no imóvel céu adusto,\nComo nunca se viu neste mundo de vivos.\n\nE os sete olhos do monstro olhavam-me, esperando\nQue a minha alma cedesse à torpeza sombria\nDos pecados mortais, cada qual mais nefando.\n\nSilêncio e morte em que me vi! Sobresaltada\nA minha alma acordou, e o dragão que eu temia,\nFugindo, ante o sinal da cruz desfez-se em nada..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, XII.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ascetas": {"t":["::parte XIII\n::parte I\n\nAscetas imortais da Idade-Média, os joelhos\nSangraram-vos de tanto orar: o olhar contrito,\nSeguindo o olhar de Deus nos ocasos vermelhos,\nFugiu-vos para o céu, sedento de infinito.\n\nAs nuvens para vós eram como evangelhos,\nPáginas onde a mão de Deus havia escrito.\nE vós lieis por lá, ansiosos como os velhos,\nO roteiro estelar de um destino bendito.\n\nSe eu podesse viver a vossa doce vida,\nNo mistério final de um mosteiro de treva,\nOnde se ia apagar tanta alma dolorida...\n\nViver longe da carne ardente, da luxúria\nQue para nos tentar em cada peito eleva,\nComo frutos de luz, duas tetas de fúria!\n\n::parte II\n\nPudesse eu, pudesse eu viver acima disto,\nOnde... não sei, e nem me importa a mim sabê-lo.\nEm um logar em que de ninguém fosse visto,\nEnvolta a fronte num fulgor de setestrelo.\n\nE lá, junto a meu Pai celeste, ouvindo a Cristo,\nFonte de luz, feliz por tão de perto vê-lo,\nTodo branco de luar, ser o filho bem quisto\nA quem o pai afaga e beija-lhe o cabelo.\n\nViver em pleno mundo azul, longe do nivel\nComum para quem é mortal, sempre ajoelhado,\nNa santa comunhão de um amor impassível.\n\nSer um Eleito, bem longe da humana vida,\nSer o Cordeiro que vai ser sacrificado,\nE vê na luz do céu a terra prometida."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, XIII.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** 2 sonetos.\n\n**Notas sobre o texto.**\n\nNo verso 8 do primeiro soneto a edição traz \"lieis\" (\"E vós lieis por lá\"); forma mantida como no impresso (leitura do OCR)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-mors": {"t":["Fica bem longe o meu principado,\nEntre montanhas que não têm verdura.\n(Meu dolorido coração, cuidado!\nHá muito tempo o temporal perdura.)\n\nVivo no meu castelo avassalado\nA uma rainha sem formosura.\nTenho chorado, tenho soluçado,\nComo vós mortais que a julgais impura.\n\nSegue-me o Tédio, todo de preto...\nE a sublime Rainha dá-me o braço,\nQue é branco porque é braço de esqueleto.\n\n— Mandai, Senhora, aprontar a eça...\n(Oh chancelier sombrio do meu paço,\nO cantochão dos sinos já começa.)"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput II, Os sonetos, XIV.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-sam-bom-jesus-de-mattosinhos": {"t":["::dedicatoria A José Severiano de Rezende, Presbit.\n\nSão Bom Jesus de Matosinhos\nFez a Capela em que o adoramos\nNo meio de árvores e ramos\nPara ficar perto dos ninhos.\n\nÉ como a Igreja de uma aldeia,\nTão socegada e tão singela...\nAs moças, quando a lua é cheia,\nSentam-se à porta da Capela.\n\nVai-se pela ladeira acima\nAté chegar no alto do morro.\nTão longe... mas quem desanima\nSe ele é o Senhor do Bom-Socorro!\n\nE atraz da Igreja o cemitério\nFloresce cheio de jazigos.\nOs próprios mortos, que mistério!\nVivem na paz de bons amigos.\n\nQuando o Jubileu se aproxima,\nAi! quanta gente sobe o morro...\nTão longe... mas quem desanima\nSe Ele é o Senhor do Bom-Socorro!\n\nVelhas de oitenta anos contados\nQuerem vê-lo no seu altar,\nBraços abertos, mas pregados,\nQue nos não podem abraçar.\n\nEntrevados de muitos anos,\nVão de rastros pelos caminhos\nOlhar os olhos tão humanos\nDe Bom Jesus de Matosinhos.\n\nSaem dos leitos como de eças,\nEspectros cheios de esperança,\nE vão cumprir loucas promessas,\nPois de esperar a fé não cança.\n\nVinde leprosos do grande ermo,\nAlmas que estais dentro de lodos:\nQue o Bom Jesus recebe a todos,\nOu seja o são ou seja o enfermo.\n\nAlmas sem rumo como as vagas,\nVinde rezar, vinde rezar!\nSe Ele também tem tantas chagas,\nComo não há de vos curar...\n\nDireis talvez: «Chegar lá em cima...\nAntes de lá chegar eu morro!\nTão longe...» Mas quem desanima\nSe Ele é o Senhor do Bom Socorro!\n\nFoi pelo meiado de Setembro,\nNo Jubileu, que eu vim amá-la.\nAinda com lágrimas relembro\nAqueles olhos cor de opala...\n\nEra tarde. O sol no poente\nBaixava lento. A noite vinha.\nEla tossia, estava doente...\nMeu Deus, que olhar o que ela tinha!\n\nEla tossia. Pelos ninhos,\nCantava a noite, toda luar.\nSão Bom Jesus de Matosinhos\nOlhava-a como que a chorar..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput III.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (14 estrofes, 56 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-a-catedral": {"t":["::dedicatoria Ao Dr. Dario da Silva\n::epigrafe Ignota landa astral da Bem-Aventurança, / Já não ha sobre a terra o que eu chamo esperança, (José Severiano de Rezende, Presbyt.)\n\nD. Guiomar tombou de giolhos,\nDobravam todolos sinos —\nE no horizonte dos seus olhos\nDois Anjos cantaram hinos.\n\nAs mãos em cruz, a alma petrina\nSuspendendo os alvos peitos.\nQue amargura quase-divina\nNos seus olhos contrafeitos!\n\nEra no tempo em que a moirama\nDominava a Portugal.\nComo rezaste, nobre Dama,\nNessa noite de Natal...\n\n—«Senhor meu Deus onipotente,\nOuvide a voz de uma louca...\n(Bem se via que uma alma crente\nTe soluçava na boca.)\n\n«Senhor meu Deus de alta clemência,\nEis o que hoje vos imploro:\nSeja eterna a minha existência\nNeste deserto onde moro.\n\n«A Catedral que vos levanto\nÉ feita de pedra e cal...\nSenhor Deus, que eu exista emquanto\nExistir a Catedral!»\n\nForam palavras céu arriba,\nClamaram no mar profundo...\nOuviu-as Deus, e um velho escriba\nAnotou-as cá no mundo.\n\nE mesterais dos mais valentes\nVão começando o trabalho;\nQual quebra as pedras em torrentes,\nQual as prepara com o malho.\n\nTamanho esforço sobre-humano\nPõe de pé a Catedral.\nE já passara mais um ano,\nE outra noite de Natal.\n\nNão têm mais conta os dobrões de oiro\nQue a Dama gastou na Igreja.\nFosse embora mais de um tesoiro\nEis acabada a peleja.\n\nDona Guiomar está contente,\nToda ledice na face.\nPor não morrer, ri-se da gente...\nNão houve quem lá invejasse.\n\nLastima o tempo em que era forte,\nBenfadada e benquerida.\nSe reza agora, pede a morte,\nSó por ter eterna vida.\n\nComo o Senhor há de ouvi-la,\nSe não tomba a Catedral?\n— Dorme, Fidalga, bem tranquila,\nQue não tem cura o teu mal.\n\nE para ela um caixão foi feito:\nE nele o corpo deitando,\nDona Guiomar, com as mãos ao peito,\nPôs-se esperando, esperando...\n\nSéculos passam no infinito,\nE ela está sempre deitada,\nSem um gemido, sem um grito,\nDe olhos fitos sem ver nada.\n\nJunto à Dama quase-defunta\nReza um padre no Natal.\nDona Guiomar então pergunta\nSe tombou a Catedral..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput IV.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Quadras (16 estrofes, 64 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ossa-mea-i": {"t":["Desesperanças! requiem tumultuário\nNa abandonada igreja sem altares...\nA noite é branca, o esquife é solitário,\nE a cova, ao longe, espreita os meus pesares.\n\nSinos que dobram, dobras de sudário!\nNo silêncio das horas tumulares\nHá de surgir o espectro funerário,\nCujos olhos sem luz não têm olhares.\n\nSanto alívio de paz, consolo pio,\nFonte clara no meio do deserto,\nManto que cobre aqueles que têm frio!\n\nEis-me esperando o derradeiro trono;\nQue a morte vem de manso, em dia incerto,\nE fecha os olhos dos que têm mais sono..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput V, Ossa Mea (sonetos), I.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ossa-mea-ii": {"t":["Mãos de finada, aquelas mãos de neve,\nDe tons marfíneos, de ossatura rica,\nPairando no ar, num gesto brando e leve,\nQue parece ordenar mas que suplica.\n\nErguem-se ao longe como se as eleve\nAlguém que ante os altares sacrifica:\nMãos que consagram, mãos que partem breve,\nMas cuja sombra nos meus olhos fica...\n\nMãos de esperança para as almas loucas,\nBrumosas mãos que vêm brancas, distantes,\nFechar ao mesmo tempo tantas bocas...\n\nSinto-as agora, ao luar, descendo juntas,\nGrandes, maguadas, pálidas, tateantes,\nCerrando os olhos das visões defuntas..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput V, Ossa Mea (sonetos), II.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ossa-mea-iii": {"t":["::dedicatoria Ao meu primo Alfredo da Costa Guimarães\n\nQuero crer, olhos meus em penitência,\nQue na magua da eterna despedida,\nVos terei transformados na áurea essência\nDe dois astros de luz amortecida...\n\nInvocareis então a alta Clemência\nPara a minha alma triste e dolorida,\nNo instante em que eu, sublime de inocência,\nMurmurar-vos assim, deixando a vida:\n\nOlhos de olhar o mundo contristados,\nEis-vos agora alem, nesse mistério\nDe epitalâmios e de astrais noivados.\n\nVede bem que estes restos foram vossos:\nIluminai, com resplendor funéreo,\nEm noite longa a cinza dos meus ossos..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput V, Ossa Mea (sonetos), III.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ossa-mea-iv": {"t":["Oh lábios que sereis de lodo e poeira,\nQue intangível desejo vos abate?\nQue ânsia suprema, na hora derradeira,\nEm silêncio vos livra esse combate?\n\nQuereis falar, e quietos sois: na inteira\nMudez do coração que já não bate.\nPor debaixo de vós ri-se a caveira,\nLábios que fostes flamas de escarlate.\n\nSe frios como neve estais agora,\nCom saudades de beijos que não destes,\nAlegrai-vos na dor que vos descora.\n\nCerrai-vos para sempre em doce calma:\nQue os beijos dados, e ainda os mais celestes,\nNunca deixam vestígios na nossa alma..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput V, Ossa Mea (sonetos), IV.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ossa-mea-vi": {"t":["Ah! tantas ilusões, para as perdermos,\nE os sonhos onde iremos enterrá-los!\nSempre o luar na solidão sem termos,\nE estes corpos a encher covas e valos,\n\nVamos chorar alem, naqueles ermos.\nQuem poderá sofrer tantos abalos!\nOs pobres corações estão enfermos,\nE o consolo de Deus deve salvá-los.\n\nTomba de joelhos, tu que não soubeste\nGozar a paz que veio sobre as ondas\nDa tua alma ao clarão da noite agreste.\n\nNoivo da Morte, em branca primavera,\nSe acaso tens um leito onde te escondas,\nAperta a mão piedosa que te espera..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput V, Ossa Mea (sonetos), VI.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-ossa-mea-vii": {"t":["::dedicatoria Ao meu irmão Artur da Costa Guimarães\n\nSe eu procurasse a minha cova ausente,\nBem pode ser à beira desta estrada\nAnte a minha alma a visse de repente,\nBoca vazia ao luar escancarada...\n\nMas nessa hora de horrores que pungente\nEspanto! Alma no amor crucificada,\nBranca, fugindo silenciosamente,\nTalvez que o teu olhar não visse nada.\n\nTanto é certo, meu Deus, na vida impura,\nNão podermos saber onde marcados\nEstão os palmos de cada sepultura...\n\nPois, talvez, ao crepusculo indeciso\nQue me encaminha os passos fatigados,\nSeja-me a cova o chão que agora piso..."],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Caput V, Ossa Mea (sonetos), VII.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Soneto.","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-kiriale-epilogo-dies-irae": {"t":["::dedicatoria A Mário de Alencar\n\nOh! dia de ira aquele dia!\nDi-lo David, e a Pitonisa:\nRevolve o mundo em cinza fria.\n\nMas que pavor haverá quando\nVier Aquele que pesquisa\nAs obras do homem miserando!\n\nPelas regiões do eterno sono\nSoa a fatal tuba da Crença,\nReunindo a todos ante o Trono.\n\nA morte e a natureza, pasmas,\nVêm, ante Deus que os julga, a imensa\nRessurreição desses fantasmas.\n\nTudo que tem de ser julgado\nHá de surgir num livro de onde\nO clamor se ouve do pecado.\n\nE Aquele que os mortos reune\nHá de julgar o que se esconde,\nNada ficará impune.\n\nQue direi ante o Trono augusto?\nSó tu, com as tuas vestes alvas,\nNão sofrerás, Alma do Justo!\n\nRei de tremenda majestade,\nOs que serão salvos tu salvas:\nSalva-me, oh! fonte da piedade.\n\nDa tua Sacrosanta Via\nA causa fui, Jesus Piedoso:\nNão me percas naquele dia.\n\nCom fadigas, suores e pranto,\nTu me buscaste sem repouso:\nNão se perca trabalho tanto.\n\nOh! meu Senhor Deus de vingança,\nAntes d'aquele dia extremo,\nO teu perdão sobre mim lança.\n\nComo réu, eis-me suplicante...\nCom o rosto em fogo choro e gemo;\nPerdoa esta alma agonisante.\n\nComo, Jesus, me esperançaste\nQuando ouviste o ladrão contrito\nE a Madalena tu perdoaste!\n\nÉ indigna a prece que em mim clama:\nFaze por teu favor bendito\nQue me não queime a eterna chama.\n\nA mim entre as ovelhas deita,\nLonge dos bodes condenados,\nDe ti, Jesus, à mão direita.\n\nAh! se os malditos tu condenas,\nPõe-me com os bem-aventurados,\nLivre das sempiternas penas.\n\nCuida em mim na hora derradeira...\nDia de lágrimas! pois o homem\nHá de surgir da cinza e poeira.\n\nDo teu perdão abrindo as portas,\nLivra-o das chamas que o consomem,\nRequiem eterno aos que estão mortos!\n\n::data São Paulo e Vila Rica (1891-1895)"],"e":{"apresentacao":"**Publicação.** Kiriale (1902), Epílogo.\n\n**Ortografia.** Atualizada (fonte: Kiriale, Porto, Typographia Universal, 1902)\n\n**Forma.** Tercetos (18 estrofes, 54 versos)","fontes":[{"nome":"Brasiliana USP","url":"https://digital.bbm.usp.br/ (Brasiliana USP, exemplar da Biblioteca Guita e José Mindlin: Kiriale, Porto, 1902)"}]}},
"alphonsus-de-guimaraens-pastoral-olhos": {"t":["Olhos sublimes, sombras chinesas,\nSob a arcaria das sobrancelhas...\nSolar magnífico, onde princesas\nPassam de túnicas vermelhas...\n\nOlhos de poente, luares remotos\nPor entre torres inacessíveis...\nRosas e lírios, goivos e lotos,\nRoxas violetas impassíveis...\n\nOlhos viúvos, santos, blasfemos,\nLadainha dos Sete Pecados...\nNuvens doiradas de crisantemos,\nSonhos de místicos noivados...\n\nOlhos pungentes, que chorais tanto,\nDias de luto, noites em calma...\nInstrumentados por algum Santo\nPara o responso da minh'alma...\n\nOlhos profundos, florindo juntos,\nCheios do sangue dos sacrifícios...\nEças armadas para defuntos,\nDobres dos últimos ofícios...\n\nOlhos, olhares evocadores\nDe espectros mudos de altivo porte...\nFechai a campa dos meus amores,\nOficiantes da minha morte!"],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), As Canções, IV.\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Quadras (6 estrofes, 24 versos)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/Olhos"}]}},
"alphonsus-de-guimaraens-pastoral-cisnes-brancos": {"t":["Ó cisnes brancos, cisnes brancos,\nPorque viestes, se era tão tarde?\nO sol não beija mais os flancos\nDa montanha onde morre a tarde.\n\nÓ cisnes brancos, dolorida,\nMinh'alma sente dores novas.\nCheguei à terra prometida:\nÉ um deserto cheio de covas.\n\nVoai para outras risonhas plagas,\nCisnes brancos! Sede felizes...\nDeixai-me só com as minhas chagas,\nE só com as minhas cicatrizes.\n\nVenham as aves agoireiras,\nDe risada que esfria os ossos...\nMinh'alma, cheia de caveiras,\nEstá branca de padre-nossos.\n\nQueimando a carne como brasas,\nVenham as tentações daninhas,\nQue eu lhes porei, bem sob as asas,\nA alma cheia de ladainhas.\n\nÓ cisnes brancos, cisnes brancos,\nDoce afago de alva plumagem!\nMinh'alma morre aos solavancos\nNesta medonha carruagem..."],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), As Canções, V.\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Quadras (6 estrofes, 24 versos)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/Cysnes_brancos"}]}},
"alphonsus-de-guimaraens-pastoral-minh-alma-e-a-torre-de-uma-igreja": {"t":["Minh'alma é a torre de uma igreja:\nPassa de luto o sacristão...\nA coruja que nela adeja\nÉ o meu próprio coração.\n\nE o sacristão que nunca dorme\n(E' um esqueleto que não conheço.)\nSobe a escadaria enorme\nQue não tem fim nem tem começo.\n\nSobe e põe-se lá de cima,\nComo dolente trovador que é,\nA dizer versos onde a rima\nÉ a uncção de um peito cheio de fé.\n\nSão salmos tristes, mortuários,\nProfundas preces de penitência.\nSurgem imagens de calvários,\nNo fim de cada uma existência.\n\nMatinas, vésperas, completas,\nSoluçam na sua voz.\nSeguem-se horas de silêncio, inquietas,\nDe uma agonia atroz.\n\nE o sacristão, todo de preto,\nBeija o retrato de uma dama.\nÉ bem gentil este esqueleto\nFazendo um gesto de quem ama.\n\nSó neste instante é que, fitando\nOs finos ossos que Deus me deu,\nMe reconheço no miserando\nEspectro vil: sou eu! sou eu!\n\nQuando morre quem quer que seja,\nO sacristão põe-se a rezar.\nMinh'alma é a torre de uma igreja,\nQue tem um sino sempre a dobrar..."],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), As Canções, VII.\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Quadras (8 estrofes, 32 versos)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/Minh%E2%80%99alma_%C3%A9_a_torre_de_uma_egreja"}]}},
"alphonsus-de-guimaraens-pastoral-o-cinamomo-floresce": {"t":["O cinamomo floresce\nEm frente do teu postigo:\nCada flor murcha que desce\nMorre de sonhar comtigo.\n\nE as folhas verdes que vejo\nCaídas por sobre o solo,\nChamadas pelo teu beijo\nVão procurar o teu colo.\n\nAi! Senhora, se eu pudesse\nSer o cinamomo antigo\nQue em flores roxas floresce\nEm frente do teu postigo!\n\nVerias talvez, ai! como\nSão tristes em noite calma\nAs flores do cinamomo\nDe que está cheia a minh'alma!"],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), As Canções, XXV.\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Quadras (4 estrofes, 16 versos)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/O_cinnamomo_floresce"}]}},
"alphonsus-de-guimaraens-pastoral-ismalia": {"t":["Quando Ismália enlouqueceu,\nPôs-se na torre a sonhar...\nViu uma lua no céu,\nViu outra lua no mar.\n\nNo sonho em que se perdeu,\nBanhou-se toda em luar...\nQueria subir ao céu,\nQueria descer ao mar...\n\nE no desvario seu,\nNa torre pôs-se a cantar...\nEstava perto do céu,\nEstava longe do mar...\n\nE como um anjo pendeu\nAs asas para voar...\nQueria a lua do céu,\nQueria a lua do mar...\n\nAs asas que Deus lhe deu\nRuflaram de par em par...\nSua alma subiu ao céu,\nSeu corpo desceu ao mar..."],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), As Canções, XXXIII.\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Quadras (5 estrofes, 20 versos)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/Ysmalia"}]}},
"alphonsus-de-guimaraens-pastoral-vagueiam-suavemente-os-teus-olhares": {"t":["Vagueiam suavemente os teus olhares\nPelo amplo céu franjado em linho:\nComprazem-te as visões crepusculares...\nTu és uma ave que perdeu o ninho.\n\nEm que nichos doirados, em que altares\nRepoisas, anjo errante, de mansinho?\nE penso, ao ver-te envolta em véus de luares,\nQue vês no azul o teu caixão de pinho.\n\nÉs a essência de tudo quanto desce\nDo solar das celestes maravilhas...\nHarpa dos crentes, cítola da prece...\n\nLua eterna que não tivesse fases,\nCintilas branca, imaculada brilhas,\nE poeiras de astros nas sandálias trazes..."],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), Os Sonetos, IV.\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.\n\n**Notas sobre o texto.**\n\nTexto do Wikisource em grafia moderna (não copiado do fac-símile de 1923); o v2 tem só 8 sílabas na fonte, provável lacuna do transcritor (\"Pelo amplo céu franjado em linho:\")","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Vagueiam_suavemente_os_teus_olhares"}]}},
"alphonsus-de-guimaraens-pastoral-rosas-que-ja-vos-fostes-desfolhadas": {"t":["Rosas que já vos fostes, desfolhadas\nPor mãos também que já se foram, rosas\nSuaves e tristes! Rosas que as amadas,\nMortas também, beijaram suspirosas...\n\nUmas rubras e vans, outras fanadas,\nMas cheias do calor das amorosas...\nSois aroma de alfombras silenciosas\nOnde dormiram tranças destrançadas.\n\nUmas brancas, da cor das pobres freiras,\nOutras cheias de viço e de frescura,\nRosas primeiras, rosas derradeiras!\n\nAi! quem melhor que vós, se a dor perdura,\nPara coroar-me, rosas passageiras,\nO sonho que se esvai na desventura?"],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), Os Sonetos, XII.\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/Rosas_que_j%C3%A1_vos_fostes%2C_desfolhadas"}]}},
"alphonsus-de-guimaraens-pastoral-hao-de-chorar-por-ela-os-cinamomos": {"t":["Hão de chorar por ela os cinamomos,\nMurchando as flores ao tombar do dia.\nDos laranjais hão de cair os pomos,\nLembrando-se daquela que os colhia.\n\nAs estrelas dirão: — Ai! nada somos,\nPois ela se morreu, fulgente e fria...\nE pondo os olhos nela como pomos,\nHão de chorar a irman que lhes sorria.\n\nA lua, que lhe foi mãe carinhosa,\nQue a viu nascer e amar, há de envolvê-la\nEntre lírios e pétalas de rosa.\n\nOs meus sonhos de amor serão defuntos...\nE os arcanjos dirão no azul, ao vê-la,\nPensando em mim: — Porque não vieram juntos?"],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), Os Sonetos, XIX.\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/H%C3%A3o_de_chorar_por_ella_os_cinnamomos"}]}},
"alphonsus-de-guimaraens-pastoral-a-catedral": {"t":["Entre brumas ao longe surge a aurora,\nO hialino orvalho aos poucos se evapora,\nAgoniza o arrebol.\nA catedral ebúrnea do meu sonho\nAparece na paz do céu risonho\nToda branca de sol.\n\nE o sino canta em lúgubres responsos:\nPobre Alphonsus! Pobre Alphonsus!\n\nO astro glorioso segue a eterna estrada.\nUma áurea seta lhe cintila em cada\nRefulgente raio de luz.\nA catedral ebúrnea do meu sonho,\nOnde os meus olhos tão cançados ponho,\nRecebe a bençam de Jesus.\n\nE o sino clama em lúgubres responsos:\nPobre Alphonsus ! Pobre Alphonsus!\n\nPor entre lírios e lilazes desce\nA tarde esquiva: amargurada prece\nPõe-se a lua a rezar.\nA catedral ebúrnea do meu sonho\nAparece na paz do céu tristonho\nToda branca de luar.\n\nE o sino chora em lúgubres responsos:\nPobre Alphonsus! Pobre Alphonsus!\n\nO céu é todo trevas: o vento uiva.\nDo relâmpago a cabeleira ruiva\nVem açoitar o rosto meu.\nE a catedral ebúrnea do meu sonho\nAfunda-se no caos do céu medonho\nComo um astro que já morreu.\n\nE o sino geme em lúgubres responsos:\nPobre Alphonsus! Pobre Alphonsus!\n\n::data Julho — 14, de 1914."],"e":{"apresentacao":"**Publicação.** Pastoral aos Crentes do Amor e da Morte (1923), A Catedral (poema final)\n\n**Ortografia.** Atualizada (fonte: Pastoral aos crentes do amor e da morte, 1923)\n\n**Forma.** Sextilhas alternadas com dísticos de refrão (32 versos)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pastoral_aos_crentes_do_amor_e_da_morte_(1923)/A_Cathedral"}]}},
"alphonsus-de-guimaraens-pulvis-entre-alvas-acucenas-olvidado": {"t":["Entre alvas açucenas olvidado\n(Como S. João da Cruz, que assim o disse),\nQue eu para o céu em noite ideal partisse\nQuis o destino meu, quis o meu fado.\n\nQuem fez que a lua em pleno céu florisse,\nFez florescer em mim o lírio amado:\nAlcatifas suntuosas de noivado\nQuis Deus que em oração minh'alma visse.\n\nFiquei (doces momentos de ventura!)\nHaurindo a luz que desce das estrelas\nÀ terra, onde de novo os pés eu ponho...\n\nEmbriaguei-me na eterna formosura:\nE as minhas hiperdúlias, pude vê-las\nNa alcândora celeste do meu sonho..."],"e":{"apresentacao":"**Publicação.** Pulvis (1938)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Entre_alvas_açucenas_olvidado"}]}},
"alphonsus-de-guimaraens-avulsos-cantem-outros-a-clara-cor-virente": {"t":["Cantem outros a clara cor virente\nDo bosque em flor e a luz do dia eterno...\nEnvoltos nos clarões fulvos do oriente,\nCantem a primavera: eu canto o inverno.\n\nPara muitos o imoto céu clemente\nÉ um manto de carinho suave e terno:\nCantam a vida, e nenhum deles sente\nQue decantando vai o próprio inferno.\n\nCantem esta mansão, onde entre prantos\nCada um espera o sepulcral punhado\nDe úmido pó que há de abafar-lhe os cantos...\n\nCada um de nós é a bússola sem norte.\nSempre o presente pior do que o passado.\nCantem outros a vida: eu canto a morte..."],"e":{"apresentacao":"**Publicação.** Poesias (livro não indicado na fonte)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Cantem_outros_a_clara_cor_virente"}]}},
"alphonsus-de-guimaraens-avulsos-como-se-moco-e-nao-bem-velho-eu-fosse": {"t":["Como se moço e não bem velho eu fosse,\nUma nova ilusão veio animar-me,\nNa minh'alma floriu um novo carme,\nO meu ser para o céu alcandorou-se.\n\nOuvi gritos em mim como um alarme.\nE o meu olhar, outrora suave e doce,\nNas ânsias de escalar o azul, tornou-se\nTodo em raios, que vinham desolar-me.\n\nVi-me no cimo eterno da montanha\nTentando unir ao peito a luz dos círios\nQue brilhavam na paz da noite estranha.\n\nAcordei do áureo sonho em sobressalto;\nDo céu tombei ao caos dos meus martírios,\nSem saber para que subi tão alto..."],"e":{"apresentacao":"**Publicação.** Poesias (livro não indicado na fonte)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Como_se_moço_e_não_bem_velho_eu_fosse"}]}},
"alphonsus-de-guimaraens-avulsos-deus-e-a-luz-celestial-que-os-astros-unge-e-veste": {"t":["Deus é a luz celestial que os astros unge e veste,\nE dessa eterna luz nós todos fomos feitos.\nUm fulgor de orações brilha nos nossos peitos:\nÉ o reflexo estelar dessa origem celeste.\n\nO homem mais louco e vil, cuja alma ímpia se creste\nAos fogos infernais dos mais torpes defeitos,\nDe vez em quando sente esplendores eleitos,\nQue tombam nele como o luar sobre um cipreste.\n\nQuem não sentiu no peito a carícia divina,\nA enchê-lo de clarões na transparência hialina\nDe um astro que cintila em pleno azul sem véus?\n\nTudo é luz na nossa alma, e o mais vil, o mais louco,\nBem sabe que esta vida é um sol que dura pouco\nE que Deus vive em nós como dentro dos céus..."],"e":{"apresentacao":"**Publicação.** Poesias (livro não indicado na fonte)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Deus_é_a_luz_celestial_que_os_astros_unge_e_veste"}]}},
"alphonsus-de-guimaraens-avulsos-encontrei-te-era-o-mes": {"t":["Encontrei-te. Era o mês... Que importa o mês? agosto,\nSetembro, outubro, maio, abril, janeiro ou março,\nBrilhasse o luar, que importa? ou fosse o sol já posto,\nNo teu olhar todo o meu sonho andava esparso.\n\nQue saudades de amor na aurora do teu rosto,\nQue horizonte de fé no olhar tranqüilo e garço!\nNunca mais me lembrei se era no mês de agosto,\nSetembro, outubro, maio, abril, janeiro ou março.\n\nEncontrei-te. Depois... depois tudo se some:\nDesfaz-se o teu olhar em nuvens de ouro e poeira...\nEra o dia... Que importa o dia, um simples nome?\n\nOu sábado sem luz, domingo sem conforto,\nSegunda, terça ou quarta ou quinta ou sexta-feira,\nBrilhasse o sol, que importa? ou fosse o luar já morto!"],"e":{"apresentacao":"**Publicação.** Poesias (livro não indicado na fonte)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Encontrei-te._Era_o_mês..."}]}},
"alphonsus-de-guimaraens-avulsos-ninguem-anda-com-deus-mais-do-que-eu-ando": {"t":["Ninguém anda com Deus mais do que eu ando,\nNinguém segue os seus passos como sigo.\nNão bendigo a ninguém, e nem maldigo:\nTudo é morto num peito miserando.\n\nVejo o sol, vejo a lua e todo o bando\nDas estrelas no olímpico jazigo.\nA misteriosa mão de Deus o trigo\nQue ela plantou aos poucos vai ceifando.\n\nE vão-se as horas em completa calma.\nUm dia (já vem longe ou já vem perto?)\nTudo que sofro e que sofri se acalma.\n\nAh se chegasse em breve o dia incerto!\nFar-se-á luz dentro em mim, pois a minh'alma\nSerá trigo de Deus no céu aberto..."],"e":{"apresentacao":"**Publicação.** Poesias (livro não indicado na fonte)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ninguém_anda_com_Deus_mais_do_que_eu_ando"}]}},
"alphonsus-de-guimaraens-avulsos-sempre-vivi-com-a-morte-dentro-da-alma": {"t":["Sempre vivi com a morte dentro da alma,\nSempre tateei nas trevas de um jazigo.\nA sombra que me envolve é eterna e calma,\nE sigo sem saber quem vai comigo.\n\nO fantasma que o coração me ensalma\nNão me ouve mais as orações que digo.\nNão existe no solo uma só palma\nPela alameda olímpica que sigo...\n\nVós que ao meu lado viestes, visionários\nDa esperança! ficastes no caminho,\nEnvolvidos nas dobras dos sudários...\n\nQue seria de mim, se eu não tivesse\nO calor subalar do teu carinho,\nÓ minha ânsia, ó meu sonho, ó minha prece!"],"e":{"apresentacao":"**Publicação.** Poesias (livro não indicado na fonte)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Sempre_vivi_com_a_morte_dentro_da_alma"}]}},
"alphonsus-de-guimaraens-avulsos-terceira-dor": {"t":["É Sião que dorme ao luar. Vozes diletas\nModulam salmos de visões contritas...\nE a sombra sacrossanta dos Profetas\nMelancoliza o canto dos levitas.\n\nAs torres brancas, terminando em setas,\nOnde velam, nas noites infinitas,\nMil guerreiros sombrios como ascetas,\nErguem ao Céu as cúpulas benditas.\n\nAs virgens de Israel as negras comas\nAromatizam com os ungüentos brancos\ndos nigromantes de mortais aromas...\n\nJerusalém, em meio às Doze Portas,\nDorme: e o luar que lhe vem beijar os flancos\nEvoca ruínas de cidades mortas."],"e":{"apresentacao":"**Publicação.** Poesias (livro não indicado na fonte)\n\n**Ortografia.** Atualizada (fonte: Wikisource, grafia moderna com trema pré-1990)\n\n**Forma.** Soneto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Terceira_dor"}]}}
});
